function polishWav(input){const audio=Buffer.from(input);if(audio.length<48||audio.toString('ascii',0,4)!=='RIFF'||audio.toString('ascii',8,12)!=='WAVE')return audio;let offset=12,dataStart=-1,dataSize=0,channels=1,sampleRate=44100,bits=0,format=0;while(offset+8<=audio.length){const id=audio.toString('ascii',offset,offset+4),size=audio.readUInt32LE(offset+4),start=offset+8;if(id==='fmt '&&size>=16){format=audio.readUInt16LE(start);channels=audio.readUInt16LE(start+2);sampleRate=audio.readUInt32LE(start+4);bits=audio.readUInt16LE(start+14)}if(id==='data'){dataStart=start;dataSize=Math.min(size,audio.length-start);break}offset=start+size+(size%2)}if(format!==1||bits!==16||dataStart<0)return audio;const samples=Math.floor(dataSize/2),view=new Int16Array(audio.buffer,audio.byteOffset+dataStart,samples);let peak=0,sum=0;for(let i=0;i<samples;i++){const v=view[i]/32768,abs=Math.abs(v);if(abs>peak)peak=abs;sum+=v*v}const rms=Math.sqrt(sum/Math.max(1,samples)),gain=Math.max(.88,Math.min(1.18,.062/Math.max(.001,rms),.82/Math.max(.001,peak))),fade=Math.min(Math.floor(sampleRate*.02)*channels,Math.floor(samples/4));for(let i=0;i<samples;i++){let envelope=1;if(i<fade)envelope=i/fade;else if(i>=samples-fade)envelope=(samples-1-i)/fade;const value=Math.round(view[i]*gain*Math.max(0,envelope));view[i]=Math.max(-32768,Math.min(32767,value))}return audio}
