function extractTurns(text){const normalized=text.replace(/[А]/g,'A').replace(/[В]/g,'B');const roles={A:[],B:[]},dialogue=[];let fallbackMap=new Map(),nextFallback='A',lastRole=null;const add=(rawRole,value)=>{let role=rawRole.toUpperCase();if(!['A','B'].includes(role)){if(!fallbackMap.has(role)){fallbackMap.set(role,nextFallback);nextFallback=nextFallback==='A'?'B':'A'}role=fallbackMap.get(role)}value=value.trim();if(value){roles[role].push(value);dialogue.push(value);lastRole=role}};for(const raw of normalized.split('\n')){const line=raw.trim();if(!line)continue;if(/^\(.+\)$/.test(line)){lastRole=null;continue}const markers=[...line.matchAll(/(^|\s)([ABFS])(?:\s*[:.)-]\s*|\s+(?=[A-ZÄÖÜ]))/g)];if(markers.length){for(let i=0;i<markers.length;i++){const start=markers[i].index+markers[i][0].length,end=i+1<markers.length?markers[i+1].index:line.length;add(markers[i][2],line.slice(start,end))}continue}if(lastRole&&!/^\s*(?:\d+[.)]|Situation|[•❖])/i.test(line)){const i=roles[lastRole].length-1;roles[lastRole][i]=`${roles[lastRole][i]} ${line}`.trim();dialogue[dialogue.length-1]=`${dialogue[dialogue.length-1]} ${line}`.trim();continue}if(/[.!?]$/.test(line)&&line.length<260&&/\b(?:ich|wir|du|sie|was|wie|wann|wo|können|möchten)\b/i.test(line))dialogue.push(line)}return {roles,dialogue}}
function parseThemes(text){const clean=String(text).replace(/\r/g,'').replace(/\n{3,}/g,'\n\n').trim();if(clean.includes('[[PAGE ')){const pages=clean.split(/\[\[PAGE \d+\]\]\n?/).filter(Boolean);const themes=[];let current=null;for(let pageIndex=1;pageIndex<pages.length;pageIndex++){const page=pages[pageIndex].trim(),number=page.match(/^\s*(\d+)\s*[.)]/)?.[1];const hasTask=number&&/(Situation|Sie |Ihre |Du |Ihr |Planen|möchten|wollen|sollen)/i.test(page.slice(0,900));if(hasTask){const firstLines=page.split('\n').map(x=>x.trim()).filter(Boolean);const taskEnd=firstLines.findIndex((x,i)=>i>0&&/^(?:A|B|F|S)(?:\s*[:.)-]|\s+)/i.test(x));const taskLines=firstLines.slice(0,taskEnd>1?taskEnd:Math.min(10,firstLines.length));const taskText=taskLines.join(' ');const keyWords=words(taskText);const prior=themes.find(t=>t.number===number&&keyWords.filter(w=>t.taskKeywords.includes(w)).length>=Math.min(3,Math.max(1,Math.floor(keyWords.length*.25))));if(prior)current=prior;else{const titleLine=taskLines.find(x=>/Situation/i.test(x))||taskLines.find((x,i)=>i>0&&x.length>20)||`Situation ${number}`;current={number,id:`t${themes.length+1}`,title:`${number}. ${titleLine.replace(/^\d+\s*[.)]?\s*/,'').slice(0,95)}`,task:taskText.slice(0,850),taskKeywords:keyWords,text:'',roles:{A:[],B:[]},dialogue:[]};themes.push(current)}}if(current){current.text=`${current.text}\n${page}`.slice(0,14000);const turns=extractTurns(page);current.roles.A.push(...turns.roles.A);current.roles.B.push(...turns.roles.B);current.dialogue.push(...turns.dialogue)}}return themes.map(({taskKeywords,number,...t})=>({...t,roles:{A:[...new Set(t.roles.A)].slice(0,45),B:[...new Set(t.roles.B)].slice(0,45)},dialogue:[...new Set(t.dialogue)].slice(0,80),keywords:words(`${t.task}\n${t.text}`).slice(0,180)})).filter(t=>t.task.length>80)}const heading=/\n(?=(?:thema|aufgabe|teil|situation|gespräch|dialog|mündlich|sprechen)\s*(?:\d+|[a-z])?\s*[:.–-]?)/gi;let blocks=clean.split(heading).filter(x=>x.trim().length>80);if(blocks.length<2){blocks=[];let current='';for(const para of clean.split(/\n\s*\n/)){if(current.length+para.length>2600&&current){blocks.push(current);current=''}current+=`${para}\n\n`}if(current)blocks.push(current)}return blocks.slice(0,100).map((block,i)=>{const lines=block.split('\n').map(x=>x.trim()).filter(Boolean),turns=extractTurns(block);const title=(lines.find(x=>x.length<110)||`Thema ${i+1}`).replace(/^[#*\d.)\s-]+/,'').slice(0,110);return {id:`t${i+1}`,title,task:lines.slice(0,6).join(' ').slice(0,650),text:block.slice(0,6000),roles:turns.roles,dialogue:turns.dialogue.slice(0,40),keywords:words(block).slice(0,120)}})}
