const writingPoints=[
  {id:'ausfluege',label:'Ausflüge',words:['ausflug','besuchen','museum','stadt','wandern','fahren','reise','sehen']},
  {id:'jahreszeit',label:'Jahreszeit',words:['frühling','sommer','herbst','winter','jahreszeit','monat','wetter']},
  {id:'kleidung',label:'Kleidung',words:['kleidung','jacke','hose','schuhe','pullover','mantel','mitbringen','anziehen']},
  {id:'vorbereitung',label:'Vorbereitung',words:['vorbereiten','vor der reise','deutsch üben','fahrkarte','buch','reservieren','ticket','koffer','information','plan','lernen']}
];
function clampScore(value){return Math.max(0,Math.min(5,Math.round(Number(value)||0)))}
function writingFallback(text){
  const lower=text.toLocaleLowerCase('de-DE'),words=text.trim().split(/\s+/).filter(Boolean),coverage=writingPoints.map(point=>{const hit=point.words.find(word=>lower.includes(word));return{id:point.id,label:point.label,covered:!!hit,evidence:hit||'',feedbackTr:hit?'Bu görev noktasına değinilmiş.':'Bu görev noktası açık bir cümleyle eklenmeli.'}}),covered=coverage.filter(x=>x.covered).length;
  const hasGreeting=/(liebe|hallo)\s+marianne/.test(lower),hasClosing=/(liebe grüße|viele grüße|bis bald|dein|deine)/.test(lower),hasSubject=/(betreff|reise|besuch)/.test(lower.slice(0,100));
  const task=clampScore(covered+(covered===4?1:0)),communication=clampScore((hasGreeting?1:0)+(hasClosing?1:0)+(hasSubject?1:0)+(words.length>=80?2:words.length>=50?1:0)),accuracy=clampScore(words.length>=80?3:2);
  return{engine:'rule-fallback',coverage,scores:{task,communication,accuracy},total:task+communication+accuracy,summaryTr:'Yerel Ollama kullanılamadığı için yapı ve görev kapsamı cihazda kurallarla kontrol edildi. Ayrıntılı dilbilgisi düzeltmesi için Ollama’yı çalıştırıp yeniden değerlendirebilirsin.',corrections:[],redemittel:['Ich schlage vor, dass wir …','Am besten kommst du im …, weil …','Du solltest … mitbringen.','Zur Vorbereitung kannst du …']}
}
function cleanWritingResult(raw,fallback){
  const byId=new Map((Array.isArray(raw.coverage)?raw.coverage:[]).map(x=>[x.id,x]));
  const coverage=writingPoints.map(point=>{const ai=byId.get(point.id),base=fallback.coverage.find(x=>x.id===point.id);return{id:point.id,label:point.label,covered:typeof ai?.covered==='boolean'?ai.covered:base.covered,evidence:String(ai?.evidence||base.evidence||'').slice(0,180),feedbackTr:String(ai?.feedbackTr||base.feedbackTr||'').slice(0,240)}});
  const scores={task:clampScore(raw.scores?.task),communication:clampScore(raw.scores?.communication),accuracy:clampScore(raw.scores?.accuracy)};
  return{engine:'ollama',coverage,scores,total:scores.task+scores.communication+scores.accuracy,summaryTr:String(raw.summaryTr||'Metin TELC B1 ölçütlerine göre incelendi.').slice(0,600),corrections:(Array.isArray(raw.corrections)?raw.corrections:[]).slice(0,6).map(c=>({original:String(c.original||'').slice(0,180),corrected:String(c.corrected||'').slice(0,180),reasonTr:String(c.reasonTr||'').slice(0,220)})).filter(c=>c.original&&c.corrected),redemittel:(Array.isArray(raw.redemittel)?raw.redemittel:[]).slice(0,5).map(x=>String(x).slice(0,180))}
}
async function telcWritingEvaluate(req,res){
  const payload=await body(req),text=String(payload.text||'').trim().slice(0,9000);if(text.split(/\s+/).filter(Boolean).length<35)return json(res,400,{error:'En az 35 kelime yazmalısın.'});
  const fallback=writingFallback(text);
  try{
    const base=safeOllama(payload.ollamaUrl),model=String(payload.model||'gemma3:4b-it-qat');
    const system=`Sen deneyimli bir telc Deutsch B1 yazma değerlendiricisisin. Öğrencinin Marianne'ye e-postasını yalnızca çalışma amaçlı değerlendir. Dört görev: ortak geziler, en iyi mevsim, getirilecek kıyafet, yolculuk hazırlığı. Resmi çalışma ölçütleri: Aufgabenbewältigung, Kommunikative Gestaltung, Formale Richtigkeit. Her ölçüte 0-5 tam sayı ver. Küçük B1 hatalarını aşırı cezalandırma. Yalnız geçerli JSON döndür: {"coverage":[{"id":"ausfluege|jahreszeit|kleidung|vorbereitung","covered":true,"evidence":"metinden kısa kanıt","feedbackTr":"Türkçe kısa geri bildirim"}],"scores":{"task":0,"communication":0,"accuracy":0},"summaryTr":"Türkçe özet","corrections":[{"original":"...","corrected":"...","reasonTr":"Türkçe"}],"redemittel":["Almanca kalıp"]}.`;
    const response=await fetch(`${base}/api/chat`,{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(35000),body:JSON.stringify({model,stream:false,format:'json',keep_alive:'20m',options:{temperature:.15,num_ctx:4096,num_predict:750,top_p:.85},messages:[{role:'system',content:system},{role:'user',content:`Öğrenci metni:\n${text}`}]})});
    if(!response.ok)throw Error('Ollama yanıt vermedi');const data=await response.json(),raw=JSON.parse(data.message?.content||'{}');return json(res,200,cleanWritingResult(raw,fallback));
  }catch{return json(res,200,fallback)}
}
